// 额外功能：监控文件变化
function watchFileChanges() {
    console.log('6. 设置文件变化监控...');
    try {
        const watcher = fs.watch(currentFile, (eventType, filename) => {
            if (eventType === 'change') {
                console.log(`   文件 ${filename} 已变化，尝试自动生效`);
                autoReload();
            }
        });
        console.log('   文件监控已启动');
        return watcher;
    } catch (error) {
        console.log(`   监控启动失败: ${error.message}`);
        return null;
    }
}

